"""Homography calibration and quality checks for one camera."""

from __future__ import annotations

import math
from collections.abc import Iterable, Sequence
from numbers import Real
from typing import (
    Any,
    NamedTuple,
)

from multivision.config import CalibrationThresholds
from multivision.errors import (
    CalibrationError,
    MultiVisionError,
)
from multivision.fiducials import CameraCorrespondences, FiducialCorrespondence
from multivision.geometry import (
    CoordinateBounds,
    HomographyPair,
    Point2D,
    calculate_convex_hull,
    calculate_polygon_area,
    is_finite_point,
    is_point_in_bounds,
    is_point_in_resolution,
    project_point,
)
from multivision.pattern import (
    APRILTAG_FAMILIES,
    CalibrationMarker,
    CalibrationPattern,
    SUPPORTED_MARKER_COUNTS,
)
from multivision.types import (
    Resolution,
    is_finite_real,
    is_valid_resolution,
)


class CalibrationMetrics(NamedTuple):
    """Measured quality of one RANSAC calibration."""

    unique_tag_count: int
    correspondence_corner_count: int
    ransac_inlier_count: int
    inlier_ratio: float
    mean_reprojection_error: float
    max_reprojection_error: float
    spatial_coverage: float
    capture_median_sigma_pixels: float | None = None
    capture_p95_sigma_pixels: float | None = None
    capture_max_sigma_pixels: float | None = None


class CalibrationResult(NamedTuple):
    """A validated camera/projector transform and its supported camera region."""

    homography: HomographyPair
    valid_region: tuple[Point2D, ...]
    metrics: CalibrationMetrics
    camera_id: str | None = None

    @property
    def projector_to_camera(self) -> tuple[tuple[float, float, float], ...]:
        return self.homography.projector_to_camera

    @property
    def camera_to_projector(self) -> tuple[tuple[float, float, float], ...]:
        return self.homography.camera_to_projector


def calibrate_homography(
    correspondences: CameraCorrespondences | Iterable[FiducialCorrespondence],
    pattern: CalibrationPattern,
    thresholds: CalibrationThresholds | None = None,
    ransac_reprojection_threshold: float = 3.0,
    cv2_module: Any | None = None,
    camera_resolution: Resolution | None = None,
) -> CalibrationResult:
    """Estimate and quality-check a projector-to-camera homography with RANSAC."""
    if not isinstance(pattern, CalibrationPattern):
        raise CalibrationError('pattern must be CalibrationPattern')
    _validate_pattern(pattern)
    checked_thresholds = thresholds if thresholds is not None else CalibrationThresholds()
    if not isinstance(checked_thresholds, CalibrationThresholds):
        raise CalibrationError('thresholds must be CalibrationThresholds')
    if camera_resolution is not None and not is_valid_resolution(camera_resolution):
        raise CalibrationError('camera_resolution must be a positive resolution')
    try:
        checked_ransac_reprojection_threshold = float(ransac_reprojection_threshold)
    except (OverflowError, TypeError, ValueError):
        raise CalibrationError(
            'ransac_reprojection_threshold must be positive and finite',
        ) from None
    if (
        not isinstance(ransac_reprojection_threshold, Real)
        or isinstance(ransac_reprojection_threshold, bool)
        or not math.isfinite(checked_ransac_reprojection_threshold)
        or checked_ransac_reprojection_threshold <= 0
    ):
        raise CalibrationError('ransac_reprojection_threshold must be positive and finite')

    checked_correspondences = _normalise_correspondences(correspondences)
    _validate_correspondences_against_pattern(checked_correspondences, pattern)
    if len(checked_correspondences) < 4:
        raise CalibrationError('At least four correspondence corners are required')
    unique_tag_count = len({item.marker_id for item in checked_correspondences})
    if unique_tag_count < checked_thresholds.min_unique_tags:
        raise CalibrationError(
            f'Calibration needs at least {checked_thresholds.min_unique_tags} unique tags',
        )

    projector_points = tuple(item.projector_position for item in checked_correspondences)
    camera_points = tuple(item.camera_position for item in checked_correspondences)
    _validate_projector_points(projector_points, pattern)
    if camera_resolution is not None and any(
        not is_point_in_resolution(point, camera_resolution)
        for point in camera_points
    ):
        raise CalibrationError(
            'Correspondences contain camera points outside the native resolution',
        )
    projector_hull = calculate_convex_hull(projector_points)
    if len(projector_hull) < 3 or len(calculate_convex_hull(camera_points)) < 3:
        raise CalibrationError('Correspondences must span two-dimensional regions')
    initial_spatial_coverage = _calculate_spatial_coverage(projector_hull, pattern)
    if initial_spatial_coverage < checked_thresholds.min_spatial_coverage:
        raise CalibrationError(
            f'Calibration spatial coverage is too small: {initial_spatial_coverage!r}',
        )

    cv2 = _load_cv2(cv2_module)
    try:
        import numpy
    except ImportError as ex:
        raise CalibrationError('NumPy is required for homography calibration') from ex

    source_array = numpy.asarray(
        [[point.x, point.y] for point in projector_points],
        dtype=numpy.float64,
    )
    destination_array = numpy.asarray(
        [[point.x, point.y] for point in camera_points],
        dtype=numpy.float64,
    )
    try:
        matrix, raw_mask = cv2.findHomography(
            source_array,
            destination_array,
            cv2.RANSAC,
            checked_ransac_reprojection_threshold,
        )
    except Exception as ex:  # noqa: BLE001 (OpenCV is an external boundary).
        raise CalibrationError('Homography estimation failed') from ex

    try:
        homography = HomographyPair.from_projector_to_camera(matrix)
    except (TypeError, ValueError, MultiVisionError) as ex:
        raise CalibrationError('OpenCV returned an invalid homography') from ex

    inlier_mask = _normalise_inlier_mask(raw_mask, len(checked_correspondences))
    ransac_inlier_count = sum(inlier_mask)
    if ransac_inlier_count < 4:
        raise CalibrationError('RANSAC did not find enough inlier corners')
    inlier_ratio = ransac_inlier_count / len(checked_correspondences)
    if inlier_ratio < checked_thresholds.min_inlier_ratio:
        raise CalibrationError(f'Calibration inlier ratio is too small: {inlier_ratio!r}')

    inlier_projector_points = tuple(
        point
        for point, is_inlier in zip(projector_points, inlier_mask)
        if is_inlier
    )
    inlier_camera_points = tuple(
        point
        for point, is_inlier in zip(camera_points, inlier_mask)
        if is_inlier
    )
    projector_hull = calculate_convex_hull(inlier_projector_points)
    camera_hull = calculate_convex_hull(inlier_camera_points)
    if len(projector_hull) < 3 or len(camera_hull) < 3:
        raise CalibrationError('RANSAC inliers must span two-dimensional regions')

    spatial_coverage = _calculate_spatial_coverage(projector_hull, pattern)
    if spatial_coverage < checked_thresholds.min_spatial_coverage:
        raise CalibrationError(
            f'Calibration spatial coverage is too small: {spatial_coverage!r}',
        )

    reprojection_errors = _calculate_reprojection_errors(
        projector_points,
        camera_points,
        homography,
        inlier_mask,
    )
    if len(reprojection_errors) == 0:
        raise CalibrationError('Calibration produced no usable reprojection metrics')
    mean_reprojection_error = sum(reprojection_errors) / len(reprojection_errors)
    max_reprojection_error = max(reprojection_errors)
    if (
        mean_reprojection_error > checked_thresholds.max_mean_reprojection_error
        or max_reprojection_error > checked_thresholds.max_reprojection_error
    ):
        raise CalibrationError(
            'Calibration reprojection error exceeds configured thresholds',
        )

    valid_region = _expand_convex_hull(camera_hull, checked_thresholds.valid_region_margin)
    metrics = CalibrationMetrics(
        unique_tag_count,
        len(checked_correspondences),
        ransac_inlier_count,
        inlier_ratio,
        mean_reprojection_error,
        max_reprojection_error,
        spatial_coverage,
    )
    camera_id = (
        correspondences.camera_id
        if isinstance(correspondences, CameraCorrespondences)
        else None
    )
    return CalibrationResult(homography, valid_region, metrics, camera_id)


def _validate_pattern(pattern: CalibrationPattern) -> None:
    if (
        not is_valid_resolution(pattern.projector_resolution)
        or not is_finite_real(pattern.projector_resolution.width)
        or not is_finite_real(pattern.projector_resolution.height)
    ):
        raise CalibrationError('pattern has an invalid projector resolution')
    if not isinstance(pattern.usable_area, CoordinateBounds):
        raise CalibrationError('pattern has an invalid usable area')
    usable_area = pattern.usable_area
    if (
        not all(
            is_finite_real(value)
            for value in (
                usable_area.left,
                usable_area.top,
                usable_area.right,
                usable_area.bottom,
            )
        )
        or not usable_area.left < usable_area.right
        or not usable_area.top < usable_area.bottom
        or usable_area.left < 0
        or usable_area.top < 0
        or usable_area.right > pattern.projector_resolution.width
        or usable_area.bottom > pattern.projector_resolution.height
    ):
        raise CalibrationError('pattern has an invalid usable area')
    if (
        not isinstance(pattern.marker_family, str)
        or pattern.marker_family not in APRILTAG_FAMILIES
    ):
        raise CalibrationError('pattern has an unsupported marker family')
    if (
        not isinstance(pattern.marker_size, Real)
        or isinstance(pattern.marker_size, bool)
        or not is_finite_real(pattern.marker_size)
        or pattern.marker_size <= 0
    ):
        raise CalibrationError('pattern has an invalid marker size')
    if (
        not isinstance(pattern.markers, tuple)
        or len(pattern.markers) not in SUPPORTED_MARKER_COUNTS
    ):
        raise CalibrationError(
            'pattern must contain 9, 10, 11, 12 or 20 markers',
        )

    marker_ids: set[int] = set()
    for marker in pattern.markers:
        if not isinstance(marker, CalibrationMarker):
            raise CalibrationError('pattern contains an invalid marker')
        if (
            not isinstance(marker.marker_id, int)
            or isinstance(marker.marker_id, bool)
            or marker.marker_id < 0
            or marker.marker_id in marker_ids
            or not isinstance(marker.corners, tuple)
            or len(marker.corners) != 4
            or not all(isinstance(corner, Point2D) for corner in marker.corners)
            or any(
                not is_finite_point(corner)
                or not is_point_in_bounds(corner, usable_area)
                for corner in marker.corners
            )
            or len(set(marker.corners)) != 4
            or not math.isfinite(marker_area := calculate_polygon_area(marker.corners))
            or marker_area <= 0
        ):
            raise CalibrationError('pattern contains an invalid marker')
        marker_ids.add(marker.marker_id)


def validate_correspondences_against_pattern(
    correspondences: Sequence[FiducialCorrespondence],
    pattern: CalibrationPattern,
) -> None:
    if not isinstance(pattern, CalibrationPattern):
        raise CalibrationError('pattern must be CalibrationPattern')
    _validate_pattern(pattern)
    _validate_correspondences_against_pattern(
        _normalise_correspondences(correspondences),
        pattern,
    )


def _validate_correspondences_against_pattern(
    correspondences: Sequence[FiducialCorrespondence],
    pattern: CalibrationPattern,
) -> None:
    pattern_markers = {marker.marker_id: marker for marker in pattern.markers}
    corner_counts: dict[int, int] = {}
    for correspondence in correspondences:
        marker = pattern_markers.get(correspondence.marker_id)
        if marker is None:
            raise CalibrationError(
                f'Correspondence refers to unknown marker {correspondence.marker_id}',
            )
        expected_projector_position = marker.corners[correspondence.corner_index]
        if correspondence.projector_position != expected_projector_position:
            raise CalibrationError('Correspondence projector corner does not match pattern')
        corner_counts[correspondence.marker_id] = (
            corner_counts.get(correspondence.marker_id, 0) + 1
        )
    if any(corner_count != 4 for corner_count in corner_counts.values()):
        raise CalibrationError('Every detected marker must provide all four corners')


def _normalise_correspondences(
    correspondences: CameraCorrespondences | Iterable[FiducialCorrespondence],
) -> tuple[FiducialCorrespondence, ...]:
    raw_values = (
        correspondences.correspondences
        if isinstance(correspondences, CameraCorrespondences)
        else correspondences
    )
    try:
        values = tuple(raw_values)
    except Exception as ex:  # noqa: BLE001 (the correspondence boundary is caller input).
        raise CalibrationError('correspondences must be iterable') from ex

    normalised: list[FiducialCorrespondence] = []
    seen_corners: set[tuple[int, int]] = set()
    for correspondence in values:
        if not isinstance(correspondence, FiducialCorrespondence):
            raise CalibrationError('correspondences must contain FiducialCorrespondence values')
        if (
            not isinstance(correspondence.marker_id, int)
            or isinstance(correspondence.marker_id, bool)
            or correspondence.marker_id < 0
            or not isinstance(correspondence.corner_index, int)
            or isinstance(correspondence.corner_index, bool)
            or not 0 <= correspondence.corner_index < 4
            or not is_finite_point(correspondence.projector_position)
            or not is_finite_point(correspondence.camera_position)
        ):
            raise CalibrationError('Correspondences contain an invalid marker corner')
        corner_key = (correspondence.marker_id, correspondence.corner_index)
        if corner_key in seen_corners:
            raise CalibrationError('Correspondences contain a duplicate marker corner')
        seen_corners.add(corner_key)
        normalised.append(
            FiducialCorrespondence(
                correspondence.marker_id,
                correspondence.corner_index,
                Point2D(*correspondence.projector_position),
                Point2D(*correspondence.camera_position),
            ),
        )
    return tuple(normalised)


def _calculate_spatial_coverage(
    projector_hull: Sequence[Point2D],
    pattern: CalibrationPattern,
) -> float:
    usable_area = pattern.usable_area
    usable_area_size = (usable_area.right - usable_area.left) * (
        usable_area.bottom - usable_area.top
    )
    if not math.isfinite(usable_area_size) or usable_area_size <= 0:
        raise CalibrationError('Calibration usable area has an invalid size')
    spatial_coverage = calculate_polygon_area(projector_hull) / usable_area_size
    if not math.isfinite(spatial_coverage):
        raise CalibrationError('Calibration spatial coverage is not finite')
    return spatial_coverage


def _validate_projector_points(
    projector_points: Sequence[Point2D],
    pattern: CalibrationPattern,
) -> None:
    if any(not pattern.usable_area.contains(point) for point in projector_points):
        raise CalibrationError('Correspondences contain projector points outside the usable area')
    if len(set(projector_points)) < 4:
        raise CalibrationError('Correspondences contain too few distinct projector points')


def _load_cv2(cv2_module: Any | None) -> Any:
    if cv2_module is not None:
        if not hasattr(cv2_module, 'findHomography') or not hasattr(cv2_module, 'RANSAC'):
            raise CalibrationError('cv2_module must provide findHomography and RANSAC')
        return cv2_module
    try:
        import cv2
    except ImportError as ex:
        raise CalibrationError('OpenCV is not installed') from ex
    return cv2


def _normalise_inlier_mask(raw_mask: object, correspondence_count: int) -> tuple[bool, ...]:
    if raw_mask is None:
        raise CalibrationError('OpenCV returned no RANSAC inlier mask')
    try:
        mask_values = tuple(raw_mask)
    except Exception as ex:  # noqa: BLE001 (OpenCV is an external boundary).
        raise CalibrationError('OpenCV returned an invalid RANSAC inlier mask') from ex
    if len(mask_values) != correspondence_count:
        raise CalibrationError('OpenCV returned an incomplete RANSAC inlier mask')
    normalised: list[bool] = []
    for value in mask_values:
        try:
            flattened_value = tuple(value)
        except TypeError:
            flattened_value = (value,)
        if len(flattened_value) != 1:
            raise CalibrationError('OpenCV returned an invalid RANSAC inlier mask')
        mask_value = flattened_value[0]
        if (
            not isinstance(mask_value, Real)
            or isinstance(mask_value, bool)
            or not math.isfinite(mask_value)
            or mask_value not in (0, 1)
        ):
            raise CalibrationError('OpenCV returned an invalid RANSAC inlier mask')
        normalised.append(bool(mask_value == 1))
    return tuple(normalised)


def _calculate_reprojection_errors(
    projector_points: Sequence[Point2D],
    camera_points: Sequence[Point2D],
    homography: HomographyPair,
    inlier_mask: Sequence[bool],
) -> tuple[float, ...]:
    errors: list[float] = []
    for projector_point, camera_point, is_inlier in zip(
        projector_points,
        camera_points,
        inlier_mask,
    ):
        if not is_inlier:
            continue
        try:
            projected_point = project_point(projector_point, homography.projector_to_camera)
        except MultiVisionError as ex:
            raise CalibrationError('Homography has an invalid reprojection') from ex
        error = math.hypot(
            projected_point.x - camera_point.x,
            projected_point.y - camera_point.y,
        )
        if not math.isfinite(error):
            raise CalibrationError('Calibration produced a non-finite reprojection error')
        errors.append(error)
    return tuple(errors)


def _expand_convex_hull(
    hull: Sequence[Point2D],
    margin: float,
) -> tuple[Point2D, ...]:
    if margin == 0:
        return tuple(hull)
    centre_x = sum(point.x for point in hull) / len(hull)
    centre_y = sum(point.y for point in hull) / len(hull)
    expanded_hull = tuple(
        Point2D(
            centre_x + (point.x - centre_x) * (1 + margin),
            centre_y + (point.y - centre_y) * (1 + margin),
        )
        for point in hull
    )
    if any(not is_finite_point(point) for point in expanded_hull):
        raise CalibrationError('Calibration valid region is not finite')
    return expanded_hull


__all__ = [
    'CalibrationError',
    'CalibrationMetrics',
    'CalibrationResult',
    'calibrate_homography',
    'validate_correspondences_against_pattern',
]

"""Pure coordinate-space and homography operations."""

from __future__ import annotations

import math
from collections.abc import Mapping, Sequence, Set
from numbers import Real
from typing import (
    NamedTuple,
    TypeAlias,
)

from multivision.errors import (
    InvalidHomographyError,
    PointOutsideCalibratedRegionError,
    PointOutsideProjectorError,
    PointOutsidePreviewError,
)
from multivision.types import (
    Resolution,
    is_finite_real,
)


class Point2D(NamedTuple):
    x: float
    y: float


class CoordinateBounds(NamedTuple):
    """A half-open rectangle in one coordinate space."""

    left: float
    top: float
    right: float
    bottom: float

    def contains(self, point: PointLike) -> bool:
        """Return whether a finite point is inside this half-open rectangle."""
        return is_point_in_bounds(point, self)


class HomographyPair(NamedTuple):
    """Both directions of one camera/projector homography."""

    projector_to_camera: tuple[tuple[float, float, float], ...]
    camera_to_projector: tuple[tuple[float, float, float], ...]

    @classmethod
    def from_projector_to_camera(cls, matrix: MatrixLike) -> 'HomographyPair':
        projector_to_camera = validate_homography(matrix)
        return cls(projector_to_camera, invert_homography(projector_to_camera))

    @classmethod
    def from_camera_to_projector(cls, matrix: MatrixLike) -> 'HomographyPair':
        camera_to_projector = validate_homography(matrix)
        return cls(invert_homography(camera_to_projector), camera_to_projector)


PointLike: TypeAlias = Point2D | Sequence[Real]
MatrixLike: TypeAlias = Sequence[Sequence[Real]]
RegionLike: TypeAlias = CoordinateBounds | Sequence[PointLike]
BoundsLike: TypeAlias = CoordinateBounds | Resolution | Sequence[int]
Polygon: TypeAlias = tuple[Point2D, ...]


class TagGeometry(NamedTuple):
    """Immutable geometry for one planar tag in one pixel coordinate space."""

    corners: tuple[Point2D, ...]
    centre: Point2D
    orientation_degrees: float
    area_px: float


class PreviewTransform(NamedTuple):
    """Aspect-preserving preview layout and its native-coordinate conversion."""

    preview_size: Resolution
    camera_resolution: Resolution
    scale: float
    content_bounds: CoordinateBounds

    def to_camera_native(self, preview_point: PointLike) -> Point2D:
        """Convert a preview-local point, rejecting letterbox padding."""
        point = coerce_point(preview_point)
        if not self.content_bounds.contains(point):
            raise PointOutsidePreviewError(
                f'Preview point {point!r} is outside the image content',
            )

        native_point = Point2D(
            (point.x - self.content_bounds.left) / self.scale,
            (point.y - self.content_bounds.top) / self.scale,
        )
        if not is_point_in_resolution(native_point, self.camera_resolution):
            raise PointOutsidePreviewError(
                f'Preview point {point!r} maps outside the camera image',
            )
        return native_point


def build_preview_transform(
    preview_size: Resolution | Sequence[int],
    camera_resolution: Resolution | Sequence[int],
) -> PreviewTransform:
    """Build an aspect-preserving, centred preview-to-native transform."""
    preview = _coerce_resolution(preview_size, 'preview_size')
    camera = _coerce_resolution(camera_resolution, 'camera_resolution')
    scale = min(preview.width / camera.width, preview.height / camera.height)
    content_width = camera.width * scale
    content_height = camera.height * scale
    left = max(0.0, (preview.width - content_width) / 2)
    top = max(0.0, (preview.height - content_height) / 2)
    return PreviewTransform(
        preview,
        camera,
        scale,
        CoordinateBounds(left, top, left + content_width, top + content_height),
    )


def preview_local_to_camera_native(
    preview_point: PointLike,
    preview_size: Resolution | Sequence[int],
    camera_resolution: Resolution | Sequence[int],
) -> Point2D:
    """Convert a preview-local point to native camera coordinates."""
    return build_preview_transform(preview_size, camera_resolution).to_camera_native(
        preview_point,
    )


def calculate_convex_hull(points: Sequence[Point2D]) -> tuple[Point2D, ...]:
    """Return the points on the convex hull in deterministic order."""
    unique_points = sorted(set(points))
    if len(unique_points) < 3:
        return tuple(unique_points)

    def cross(first: Point2D, second: Point2D, third: Point2D) -> float:
        return (
            (second.x - first.x) * (third.y - first.y)
            - (second.y - first.y) * (third.x - first.x)
        )

    lower: list[Point2D] = []
    for point in unique_points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], point) <= 0:
            lower.pop()
        lower.append(point)
    upper: list[Point2D] = []
    for point in reversed(unique_points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], point) <= 0:
            upper.pop()
        upper.append(point)
    return tuple(lower[:-1] + upper[:-1])


def calculate_polygon_area(polygon: Sequence[Point2D]) -> float:
    """Return the absolute area of an ordered polygon."""
    if len(polygon) < 3:
        return 0.0
    return abs(
        sum(
            polygon[idx].x * polygon[(idx + 1) % len(polygon)].y
            - polygon[(idx + 1) % len(polygon)].x * polygon[idx].y
            for idx in range(len(polygon))
        )
        / 2
    )


def calculate_diagonal_intersection(
    polygon: Sequence[PointLike],
) -> Point2D:
    """Return the intersection of the diagonals of an ordered quadrilateral."""
    return _calculate_diagonal_intersection(validate_planar_corners(polygon))


def _calculate_diagonal_intersection(corners: tuple[Point2D, ...]) -> Point2D:
    first_vector = Point2D(
        corners[2].x - corners[0].x,
        corners[2].y - corners[0].y,
    )
    second_vector = Point2D(
        corners[3].x - corners[1].x,
        corners[3].y - corners[1].y,
    )
    start_delta = Point2D(
        corners[1].x - corners[0].x,
        corners[1].y - corners[0].y,
    )
    denominator = _cross_product(first_vector, second_vector)
    if not math.isfinite(denominator) or denominator == 0:
        raise ValueError('Quadrilateral diagonals do not have a finite intersection')
    first_fraction = _cross_product(start_delta, second_vector) / denominator
    second_fraction = _cross_product(start_delta, first_vector) / denominator
    if (
        not math.isfinite(first_fraction)
        or not math.isfinite(second_fraction)
        or not 0 <= first_fraction <= 1
        or not 0 <= second_fraction <= 1
    ):
        raise ValueError('Quadrilateral diagonals do not intersect safely')
    intersection = Point2D(
        corners[0].x + first_fraction * first_vector.x,
        corners[0].y + first_fraction * first_vector.y,
    )
    if not is_finite_point(intersection):
        raise ValueError('Quadrilateral diagonal intersection is not finite')
    return intersection


def calculate_edge_orientation_degrees(
    edge_start: PointLike,
    edge_end: PointLike,
) -> float:
    """Return the +X-right/+Y-down angle of an ordered edge."""
    start = coerce_point(edge_start)
    end = coerce_point(edge_end)
    if start == end:
        raise ValueError('Orientation requires a finite, non-zero edge')
    orientation = math.degrees(math.atan2(end.y - start.y, end.x - start.x))
    if not math.isfinite(orientation):
        raise ValueError('Orientation requires a finite, non-zero edge')
    return ((orientation + 180.0) % 360.0) - 180.0


def calculate_polygon_orientation_degrees(
    polygon: Sequence[PointLike],
) -> float:
    """Return the ordered corner-0-to-1 orientation of a quadrilateral."""
    corners = validate_planar_corners(polygon)
    return calculate_edge_orientation_degrees(corners[0], corners[1])


def validate_planar_corners(
    corners: Sequence[PointLike],
) -> tuple[Point2D, ...]:
    """Validate and retain four finite corners in their supplied order."""
    if isinstance(corners, (Mapping, Set, str, bytes, bytearray)):
        raise ValueError('Planar tag corners must be an ordered quadrilateral')
    try:
        checked_corners = tuple(coerce_point(corner) for corner in corners)
    except (TypeError, ValueError, OverflowError):
        raise ValueError('Planar tag corners must be an ordered quadrilateral') from None
    if len(checked_corners) != 4 or len(set(checked_corners)) != 4:
        raise ValueError('Planar tag corners must contain four distinct points')
    area = calculate_polygon_area(checked_corners)
    if not math.isfinite(area) or not _has_nonzero_polygon_area(
        list(checked_corners),
    ):
        raise ValueError('Planar tag corners must have finite, non-zero area')
    if not _is_convex_ordered_polygon(checked_corners):
        raise ValueError('Planar tag corners must form a convex quadrilateral')
    return checked_corners


def build_tag_geometry(
    corners: Sequence[PointLike],
    centre: PointLike | None = None,
) -> TagGeometry:
    """Build immutable geometry from ordered planar tag corners."""
    checked_corners = validate_planar_corners(corners)
    checked_centre = (
        _calculate_diagonal_intersection(checked_corners)
        if centre is None
        else coerce_point(centre)
    )
    orientation = calculate_edge_orientation_degrees(
        checked_corners[0],
        checked_corners[1],
    )
    area = calculate_polygon_area(checked_corners)
    return TagGeometry(checked_corners, checked_centre, orientation, area)


def project_points_through_homography(
    points: Sequence[PointLike],
    homography: MatrixLike | HomographyPair,
) -> tuple[Point2D, ...]:
    """Transform finite points while rejecting a horizon-crossing homography."""
    checked_points = tuple(coerce_point(point) for point in points)
    matrix = (
        homography.camera_to_projector
        if isinstance(homography, HomographyPair)
        else homography
    )
    normalised_matrix = validate_homography(matrix)
    if len(checked_points) == 0:
        return ()
    denominators = tuple(
        normalised_matrix[2][0] * point.x
        + normalised_matrix[2][1] * point.y
        + normalised_matrix[2][2]
        for point in checked_points
    )
    if any(
        not math.isfinite(denominator)
        or abs(denominator) <= 1e-12
        for denominator in denominators
    ) or len({denominator > 0 for denominator in denominators}) != 1:
        raise InvalidHomographyError(
            'Homography has a horizon crossing in the requested points',
        )
    return tuple(project_point(point, normalised_matrix) for point in checked_points)


def project_tag_geometry(
    geometry: TagGeometry,
    homography: MatrixLike | HomographyPair,
) -> TagGeometry:
    """Project tag corners and its diagonal centre as one atomic geometry."""
    if not isinstance(geometry, TagGeometry):
        raise ValueError('geometry must be TagGeometry')
    checked_corners = validate_planar_corners(geometry.corners)
    checked_centre = coerce_point(geometry.centre)
    projected_points = project_points_through_homography(
        checked_corners + (checked_centre,),
        homography,
    )
    try:
        return build_tag_geometry(
            projected_points[:-1],
            centre=projected_points[-1],
        )
    except ValueError as ex:
        raise InvalidHomographyError(
            'Homography produced invalid planar tag geometry',
        ) from ex


def is_finite_point(point: object) -> bool:
    """Return whether a point contains exactly two finite numeric coordinates."""
    coordinates = _get_point_coordinates(point)
    if coordinates is None:
        return False
    x_value, y_value = coordinates
    return is_finite_real(x_value) and is_finite_real(y_value)


def is_point_in_bounds(point: PointLike, bounds: CoordinateBounds) -> bool:
    """Return whether a finite point is inside a half-open rectangle."""
    if not isinstance(bounds, CoordinateBounds):
        return False
    try:
        checked_point = coerce_point(point)
    except ValueError:
        return False
    if not _is_valid_bounds(bounds):
        return False
    return (
        bounds.left <= checked_point.x < bounds.right
        and bounds.top <= checked_point.y < bounds.bottom
    )


def is_point_in_resolution(
    point: PointLike,
    resolution: Resolution | Sequence[int],
) -> bool:
    """Return whether a point lies within native pixel-coordinate extents."""
    try:
        checked_resolution = _coerce_resolution(resolution, 'resolution')
    except ValueError:
        return False
    return is_point_in_bounds(
        point,
        CoordinateBounds(0, 0, checked_resolution.width, checked_resolution.height),
    )


def is_point_in_region(point: PointLike, region: RegionLike) -> bool:
    """Return whether a point is in rectangular or polygonal calibrated support."""
    if isinstance(region, CoordinateBounds):
        return is_point_in_bounds(point, region)
    if isinstance(region, (Mapping, Set)):
        return False
    try:
        checked_point = coerce_point(point)
    except ValueError:
        return False

    polygon = _normalise_polygon(region)
    if polygon is None:
        return False

    is_inside = False
    previous_point = polygon[-1]
    for current_point in polygon:
        if _is_point_on_segment(checked_point, previous_point, current_point):
            return True
        crosses_horizontal_ray = (current_point.y > checked_point.y) != (
            previous_point.y > checked_point.y
        )
        if crosses_horizontal_ray:
            crossing_x = (
                (previous_point.x - current_point.x)
                * (checked_point.y - current_point.y)
                / (previous_point.y - current_point.y)
                + current_point.x
            )
            if checked_point.x < crossing_x:
                is_inside = not is_inside
        previous_point = current_point
    return is_inside


def validate_point_in_region(point: PointLike, region: RegionLike) -> Point2D:
    """Validate and return a point supported by a calibrated region."""
    checked_point = coerce_point(point)
    if not is_point_in_region(checked_point, region):
        raise PointOutsideCalibratedRegionError(
            f'Point {checked_point!r} is outside the calibrated region',
        )
    return checked_point


def is_valid_homography(matrix: object) -> bool:
    """Return whether a matrix is finite, 3x3 and safely invertible."""
    try:
        _normalise_homography(matrix)  # type: ignore[arg-type]
    except (TypeError, ValueError, InvalidHomographyError):
        return False
    return True


def validate_homography(matrix: MatrixLike) -> tuple[tuple[float, float, float], ...]:
    """Validate and return a finite, normalised 3x3 homography."""
    return _normalise_homography(matrix)


def invert_homography(matrix: MatrixLike) -> tuple[tuple[float, float, float], ...]:
    """Invert a non-degenerate 3x3 homography without a hardware dependency."""
    normalised_matrix = _normalise_homography(matrix)
    determinant = _determinant(normalised_matrix)
    cofactors = (
        (
            normalised_matrix[1][1] * normalised_matrix[2][2]
            - normalised_matrix[1][2] * normalised_matrix[2][1],
            normalised_matrix[1][2] * normalised_matrix[2][0]
            - normalised_matrix[1][0] * normalised_matrix[2][2],
            normalised_matrix[1][0] * normalised_matrix[2][1]
            - normalised_matrix[1][1] * normalised_matrix[2][0],
        ),
        (
            normalised_matrix[0][2] * normalised_matrix[2][1]
            - normalised_matrix[0][1] * normalised_matrix[2][2],
            normalised_matrix[0][0] * normalised_matrix[2][2]
            - normalised_matrix[0][2] * normalised_matrix[2][0],
            normalised_matrix[0][1] * normalised_matrix[2][0]
            - normalised_matrix[0][0] * normalised_matrix[2][1],
        ),
        (
            normalised_matrix[0][1] * normalised_matrix[1][2]
            - normalised_matrix[0][2] * normalised_matrix[1][1],
            normalised_matrix[0][2] * normalised_matrix[1][0]
            - normalised_matrix[0][0] * normalised_matrix[1][2],
            normalised_matrix[0][0] * normalised_matrix[1][1]
            - normalised_matrix[0][1] * normalised_matrix[1][0],
        ),
    )
    return tuple(
        tuple(value / determinant for value in row)
        for row in zip(cofactors[0], cofactors[1], cofactors[2])
    )


def project_point(point: PointLike, matrix: MatrixLike) -> Point2D:
    """Project a point through a homography, rejecting invalid infinity results."""
    checked_point = coerce_point(point)
    normalised_matrix = _normalise_homography(matrix)
    projected_x = (
        normalised_matrix[0][0] * checked_point.x
        + normalised_matrix[0][1] * checked_point.y
        + normalised_matrix[0][2]
    )
    projected_y = (
        normalised_matrix[1][0] * checked_point.x
        + normalised_matrix[1][1] * checked_point.y
        + normalised_matrix[1][2]
    )
    denominator = (
        normalised_matrix[2][0] * checked_point.x
        + normalised_matrix[2][1] * checked_point.y
        + normalised_matrix[2][2]
    )
    if not math.isfinite(denominator) or abs(denominator) <= 1e-12:
        raise InvalidHomographyError('Homography projects the point to infinity')
    result = Point2D(projected_x / denominator, projected_y / denominator)
    if not is_finite_point(result):
        raise InvalidHomographyError('Homography produced a non-finite point')
    return result


def intersect_polygon_with_bounds(
    polygon: RegionLike,
    bounds: BoundsLike,
) -> Polygon | None:
    """Intersect a finite polygon with a finite rectangular bounds area.

    ``None`` is returned when the inputs are invalid or the intersection has
    no usable area.  Polygon boundaries use the closed geometric edges of the
    half-open coordinate rectangle, so a clipped edge may end at ``right`` or
    ``bottom`` while pixel-coordinate point checks remain half-open.
    """
    checked_polygon = _normalise_polygon(polygon)
    checked_bounds = _coerce_bounds(bounds)
    if checked_polygon is None or checked_bounds is None:
        return None

    clipped_polygon = checked_polygon
    for axis, boundary, keeps_greater in (
        ('x', checked_bounds.left, True),
        ('x', checked_bounds.right, False),
        ('y', checked_bounds.top, True),
        ('y', checked_bounds.bottom, False),
    ):
        clipped_polygon = _clip_polygon_against_boundary(
            clipped_polygon,
            axis,
            boundary,
            keeps_greater,
        )
        if clipped_polygon is None:
            return None

    return clipped_polygon


def project_polygon(
    polygon: RegionLike,
    homography: MatrixLike | HomographyPair,
) -> Polygon | None:
    """Project a polygon, rejecting invalid transforms and horizon crossings."""
    checked_polygon = _normalise_polygon(polygon)
    if checked_polygon is None:
        return None
    matrix = (
        homography.camera_to_projector
        if isinstance(homography, HomographyPair)
        else homography
    )
    try:
        normalised_matrix = _normalise_homography(matrix)
    except (OverflowError, TypeError, ValueError):
        return None

    denominators = tuple(
        normalised_matrix[2][0] * point.x
        + normalised_matrix[2][1] * point.y
        + normalised_matrix[2][2]
        for point in checked_polygon
    )
    if any(
        not math.isfinite(denominator)
        or abs(denominator) <= 1e-12
        for denominator in denominators
    ):
        return None
    denominator_signs = {denominator > 0 for denominator in denominators}
    if len(denominator_signs) != 1:
        return None

    try:
        projected_polygon = tuple(
            project_point(point, normalised_matrix)
            for point in checked_polygon
        )
    except InvalidHomographyError:
        return None
    return _normalise_polygon(projected_polygon)


def calculate_available_projector_area(
    camera_polygon: RegionLike,
    camera_resolution: Resolution | Sequence[int],
    homography: MatrixLike | HomographyPair,
    projector_resolution: Resolution | Sequence[int],
) -> Polygon | None:
    """Derive a usable projector polygon using a camera-to-projector transform."""
    camera_bounds = _coerce_bounds(camera_resolution)
    projector_bounds = _coerce_bounds(projector_resolution)
    if camera_bounds is None or projector_bounds is None:
        return None
    native_polygon = intersect_polygon_with_bounds(camera_polygon, camera_bounds)
    if native_polygon is None:
        return None
    projected_polygon = project_polygon(native_polygon, homography)
    if projected_polygon is None:
        return None
    return intersect_polygon_with_bounds(projected_polygon, projector_bounds)


def projector_to_camera(
    point: PointLike,
    homography: MatrixLike | HomographyPair,
) -> Point2D:
    """Transform a projector-native point into camera-native coordinates."""
    matrix = (
        homography.projector_to_camera
        if isinstance(homography, HomographyPair)
        else homography
    )
    return project_point(point, matrix)


def camera_to_projector(
    point: PointLike,
    homography: MatrixLike | HomographyPair,
) -> Point2D:
    """Transform a camera-native point into projector-native coordinates."""
    matrix = (
        homography.camera_to_projector
        if isinstance(homography, HomographyPair)
        else homography
    )
    return project_point(point, matrix)


def project_camera_points_to_projector(
    points: Sequence[PointLike],
    homography: MatrixLike | HomographyPair,
    calibrated_region: RegionLike | None = None,
    projector_resolution: Resolution | Sequence[int] | None = None,
) -> tuple[Point2D, ...]:
    """Transform supported camera points atomically and enforce output bounds."""
    checked_points = tuple(coerce_point(point) for point in points)
    if calibrated_region is not None:
        for point in checked_points:
            validate_point_in_region(point, calibrated_region)
    projected_points = project_points_through_homography(checked_points, homography)
    if projector_resolution is not None:
        for projected_point in projected_points:
            if not is_point_in_resolution(projected_point, projector_resolution):
                raise PointOutsideProjectorError(
                    f'Projected point {projected_point!r} is outside projector bounds',
                )
    return projected_points


def project_camera_to_projector(
    point: PointLike,
    homography: MatrixLike | HomographyPair,
    calibrated_region: RegionLike | None = None,
    projector_resolution: Resolution | Sequence[int] | None = None,
) -> Point2D:
    """Transform one supported camera point through the shared point path."""
    projected_points = project_camera_points_to_projector(
        (point,),
        homography,
        calibrated_region,
        projector_resolution,
    )
    return projected_points[0]


def coerce_point(point: PointLike) -> Point2D:
    coordinates = _get_point_coordinates(point)
    if coordinates is None:
        raise ValueError(f'Point must contain two finite numbers: {point!r}')
    x_value, y_value = coordinates
    if not is_finite_real(x_value) or not is_finite_real(y_value):
        raise ValueError(f'Point must contain two finite numbers: {point!r}')
    return Point2D(float(x_value), float(y_value))


def _get_point_coordinates(point: object) -> tuple[object, object] | None:
    if isinstance(point, (Mapping, Set, str, bytes, bytearray)):
        return None
    try:
        point_iterator = iter(point)  # type: ignore[arg-type]
        x_value = next(point_iterator)
        y_value = next(point_iterator)
    except (TypeError, StopIteration, ValueError):
        return None
    try:
        next(point_iterator)
    except StopIteration:
        return x_value, y_value
    return None


def _coerce_resolution(
    resolution: Resolution | Sequence[int],
    field_name: str,
) -> Resolution:
    if isinstance(resolution, Resolution):
        checked_resolution = resolution
    else:
        if isinstance(resolution, (Mapping, Set, str, bytes, bytearray)):
            raise ValueError(f'{field_name} must contain width and height')
        try:
            width, height = resolution
        except (TypeError, ValueError):
            raise ValueError(f'{field_name} must contain width and height') from None
        checked_resolution = Resolution(width, height)
    if (
        not isinstance(checked_resolution.width, int)
        or isinstance(checked_resolution.width, bool)
        or checked_resolution.width <= 0
        or not isinstance(checked_resolution.height, int)
        or isinstance(checked_resolution.height, bool)
        or checked_resolution.height <= 0
    ):
        raise ValueError(f'{field_name} must contain positive integer dimensions')
    return checked_resolution


def _coerce_bounds(bounds: BoundsLike) -> CoordinateBounds | None:
    if isinstance(bounds, CoordinateBounds):
        return bounds if _is_valid_bounds(bounds) else None
    try:
        resolution = _coerce_resolution(bounds, 'bounds')
    except (TypeError, ValueError):
        return None
    return CoordinateBounds(0, 0, resolution.width, resolution.height)


def _normalise_polygon(polygon: RegionLike) -> Polygon | None:
    if isinstance(polygon, CoordinateBounds):
        if not _is_valid_bounds(polygon):
            return None
        points = (
            Point2D(polygon.left, polygon.top),
            Point2D(polygon.right, polygon.top),
            Point2D(polygon.right, polygon.bottom),
            Point2D(polygon.left, polygon.bottom),
        )
    else:
        if isinstance(polygon, (Mapping, Set, str, bytes, bytearray)):
            return None
        try:
            points = tuple(coerce_point(point) for point in polygon)
        except (TypeError, ValueError, OverflowError):
            return None

    distinct_points: list[Point2D] = []
    for point in points:
        if len(distinct_points) == 0 or point != distinct_points[-1]:
            distinct_points.append(point)
    if len(distinct_points) > 1 and distinct_points[0] == distinct_points[-1]:
        distinct_points.pop()
    if len(distinct_points) < 3 or not _has_nonzero_polygon_area(distinct_points):
        return None
    return tuple(distinct_points)


def _clip_polygon_against_boundary(
    polygon: Polygon,
    axis: str,
    boundary: float,
    keeps_greater: bool,
) -> Polygon | None:
    clipped_points: list[Point2D] = []
    previous_point = polygon[-1]
    previous_value = previous_point.x if axis == 'x' else previous_point.y
    previous_inside = (
        previous_value >= boundary
        if keeps_greater
        else previous_value <= boundary
    )
    for current_point in polygon:
        current_value = current_point.x if axis == 'x' else current_point.y
        current_inside = (
            current_value >= boundary
            if keeps_greater
            else current_value <= boundary
        )
        if current_inside != previous_inside:
            value_delta = current_value - previous_value
            fraction = (boundary - previous_value) / value_delta
            intersection_x = previous_point.x + fraction * (
                current_point.x - previous_point.x
            )
            intersection_y = previous_point.y + fraction * (
                current_point.y - previous_point.y
            )
            if axis == 'x':
                intersection_x = boundary
            else:
                intersection_y = boundary
            clipped_points.append(Point2D(intersection_x, intersection_y))
        if current_inside:
            clipped_points.append(current_point)
        previous_point = current_point
        previous_value = current_value
        previous_inside = current_inside

    if len(clipped_points) == 0:
        return None
    return _normalise_polygon(clipped_points)


def _is_valid_bounds(bounds: CoordinateBounds) -> bool:
    return (
        is_finite_real(bounds.left)
        and is_finite_real(bounds.top)
        and is_finite_real(bounds.right)
        and is_finite_real(bounds.bottom)
        and bounds.left < bounds.right
        and bounds.top < bounds.bottom
    )


def _has_nonzero_polygon_area(polygon: list[Point2D]) -> bool:
    largest_coordinate = max(
        max(abs(point.x), abs(point.y))
        for point in polygon
    )
    if largest_coordinate == 0:
        return False

    scaled_polygon = [
        Point2D(point.x / largest_coordinate, point.y / largest_coordinate)
        for point in polygon
    ]
    twice_area = 0.0
    previous_point = scaled_polygon[-1]
    for current_point in scaled_polygon:
        twice_area += (
            previous_point.x * current_point.y
            - current_point.x * previous_point.y
        )
        previous_point = current_point
    return math.isfinite(twice_area) and abs(twice_area) > 1e-12


def _is_point_on_segment(
    point: Point2D,
    segment_start: Point2D,
    segment_end: Point2D,
) -> bool:
    cross_product = (
        (point.y - segment_start.y) * (segment_end.x - segment_start.x)
        - (point.x - segment_start.x) * (segment_end.y - segment_start.y)
    )
    if abs(cross_product) > 1e-9:
        return False
    return (
        min(segment_start.x, segment_end.x) <= point.x <= max(segment_start.x, segment_end.x)
        and min(segment_start.y, segment_end.y) <= point.y <= max(segment_start.y, segment_end.y)
    )


def _normalise_homography(matrix: MatrixLike) -> tuple[tuple[float, float, float], ...]:
    if isinstance(matrix, (Mapping, Set)):
        raise InvalidHomographyError('Homography must be a 3x3 matrix')
    try:
        raw_rows = tuple(matrix)
    except (TypeError, ValueError):
        raise InvalidHomographyError('Homography must be a 3x3 matrix') from None
    if any(isinstance(row, (Mapping, Set)) for row in raw_rows):
        raise InvalidHomographyError('Homography must be a 3x3 matrix')
    try:
        rows = tuple(tuple(row) for row in raw_rows)
    except (TypeError, ValueError):
        raise InvalidHomographyError('Homography must be a 3x3 matrix') from None
    if len(rows) != 3 or any(len(row) != 3 for row in rows):
        raise InvalidHomographyError('Homography must be a 3x3 matrix')
    if any(not is_finite_real(value) for row in rows for value in row):
        raise InvalidHomographyError('Homography must contain finite numbers')
    largest_value = max(abs(value) for row in rows for value in row)
    if largest_value == 0:
        raise InvalidHomographyError('Homography must not be all zero')
    normalised_matrix = tuple(
        tuple(float(value) / largest_value for value in row)
        for row in rows
    )
    if abs(_determinant(normalised_matrix)) <= 1e-12:
        raise InvalidHomographyError('Homography is degenerate')
    return normalised_matrix


def _determinant(matrix: tuple[tuple[float, float, float], ...]) -> float:
    return (
        matrix[0][0] * (matrix[1][1] * matrix[2][2] - matrix[1][2] * matrix[2][1])
        - matrix[0][1] * (matrix[1][0] * matrix[2][2] - matrix[1][2] * matrix[2][0])
        + matrix[0][2] * (matrix[1][0] * matrix[2][1] - matrix[1][1] * matrix[2][0])
    )


def _cross_product(first: Point2D, second: Point2D) -> float:
    return first.x * second.y - first.y * second.x


def _is_convex_ordered_polygon(polygon: Sequence[Point2D]) -> bool:
    cross_products = tuple(
        _cross_product(
            Point2D(
                polygon[(idx + 1) % len(polygon)].x - polygon[idx].x,
                polygon[(idx + 1) % len(polygon)].y - polygon[idx].y,
            ),
            Point2D(
                polygon[(idx + 2) % len(polygon)].x - polygon[(idx + 1) % len(polygon)].x,
                polygon[(idx + 2) % len(polygon)].y - polygon[(idx + 1) % len(polygon)].y,
            ),
        )
        for idx in range(len(polygon))
    )
    return all(value > 0 for value in cross_products) or all(
        value < 0 for value in cross_products
    )


