    if not isinstance(camera_slot, str) or len(camera_slot) == 0:
        raise ValueError('camera slot must be a non-empty string')
    if isinstance(value, CameraGeneration):
        generation = value
    else:
        state = getattr(value, 'state', None)
        calibration_status = getattr(value, 'calibration_status', None)
        generation = CameraGeneration(
            getattr(value, 'lifecycle_generation', 0),
            getattr(value, 'calibration_generation', 0),
